class LibraryBook:
    def __init__(self, title):
        self.title = title
        self.is_borrowed = False

    def borrow(self):
        if self.is_borrowed:
            return "이미 대출 중"
        self.is_borrowed = True
        return "대출 완료"

    def give_back(self):
        if not self.is_borrowed:
            return "대출 중이 아님"
        self.is_borrowed = False
        return "반납 완료"

